import time

from quire.transport import TransportTimeout

DEFAULT_DELAY = 0.5
MAX_DELAY = 4.0


class UploadError(Exception):
    """An upload failed after every retry."""


def upload_with_retry(send, chunk, attempts=3, delay=DEFAULT_DELAY, max_delay=MAX_DELAY):
    """Send one chunk, retrying transport timeouts with capped exponential backoff."""
    last_error = None
    for attempt in range(attempts):
        try:
            return send(chunk)
        except TransportTimeout as error:
            last_error = error
            if attempt + 1 < attempts:
                time.sleep(min(delay * (2 ** attempt), max_delay))
    raise UploadError(f"upload failed after {attempts} attempts") from last_error
